import { BaseComponent } from "../../utils/baseElement";
import styles from "./Cell.module.scss";

class Cell extends BaseComponent {
  constructor() {
    super({ tag: "button", className: styles.cell });
    this.getNode();
  }

  onRightClick(cb) {
    this.addListener("contextmenu", (event) => {
      event.preventDefault();
      this.setMark();
      cb(event);
    });
  }

  onLeftClick(cb) {
    this.addListener("click", (event) => {
      cb(event);
      this.setBackground();
    });
  }

  setBackground() {
    this.toggleClass(styles.filled, styles.empty);
  }

  setMark() {
    this.toggleClass(styles.marked, styles.empty);
  }
}
export { Cell }; //gameboard
