import { BaseComponent } from "../../../utils/baseElement";
import styles from "./Footer.module.scss";

class Footer extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor() {
    super({ tag: "footer", className: styles.footer });
    this.getNode();
    this.addGithubLink();
    this.addRSSLogo();
    this.addYear();
  }

  addGithubLink() {
    const a = new BaseComponent({
      tag: "a",
      className: styles.ghLink,
      text: "GitHub",
    });
    a.addAttributes({
      href: "https://github.com/zagorky",
      target: "_blank",
    });
    this.append(a);
  }

  addRSSLogo() {
    const a = new BaseComponent({
      tag: "a",
      className: styles.rssLogoLink,
    });
    a.addAttributes({
      href: "https://rs.school/courses/javascript",
      target: "_blank",
    });
    const logo = new BaseComponent({
      tag: "img",
      className: styles.rssLogoImg,
    });

    logo.addAttributes({
      src: "./img/logo-rsschool3.png",
      alt: "RSS Logo",
    });
    a.append(logo);
    this.append(a);
  }

  addYear() {
    const p = new BaseComponent({
      tag: "p",
      className: styles.year,
      text: "2025",
    });
    this.append(p);
  }
}

export { Footer }; //wrapper
