import { BaseComponent } from "../../../utils/baseElement";
import styles from "./Header.module.scss";

class Header extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor() {
    super({ tag: "header", className: styles.header });
    this.getNode();
    this.addLogo();
    this.addH1();
  }

  addH1() {
    const h1 = new BaseComponent({
      tag: "h1",
      className: styles.h1,
      text: "Nonorgams",
    });
    this.append(h1);
  }

  addLogo() {
    const a = new BaseComponent({
      tag: "a",
      className: styles.logoLink,
    });

    a.addAttributes({
      href: "./",
    });

    const logo = new BaseComponent({
      tag: "img",
    });

    logo.addAttributes({
      src: "./img/favicon.ico",
      alt: "Logo Nonograms",
    });

    a.append(logo);
    this.append(a);
  }

  //TODO написать таймер
  addTimer() {}
}

export { Header }; //wrapper
